insert into public.curriculum_competencies (id, course_id, academic_level, competency_area_id, statement, status) values
  ('ug-aut140-brake-systems','aut-140','undergraduate',null,'Analyze hydraulic and electronic brake-system operation, inspection findings, measurements, ABS/control evidence, and applicable service information to justify a safe diagnostic or service decision.','planned'),
  ('grad-aut510-advanced-vehicle-diagnostics','aut-510','graduate',null,'Integrate model-based, network, waveform, data, and fault-isolation evidence to evaluate competing diagnostic hypotheses and validate technically defensible conclusions.','planned'),
  ('grad-aut600-research-design','aut-600','graduate',null,'Design automotive research using focused questions, hypotheses, experimental protocols, analytical methods, uncertainty controls, validation strategies, and proposal-quality technical communication.','planned'),
  ('grad-aut610-applied-research-project','aut-610','graduate',null,'Execute and evaluate an applied automotive research project through controlled data collection, analysis, validation, technical reporting, and explicit treatment of limitations and provenance.','planned'),
  ('grad-aut620-internship','aut-620','graduate',null,'Document and critically evaluate advanced automotive professional practice using approved objectives, evidence, reflection, technical communication, and explicit institutional supervision boundaries.','planned'),
  ('grad-aut630-systems-integration','aut-630','graduate',null,'Analyze and evaluate integrated mechanical, electrical, electronic, software, communication, energy, and control-system interfaces using systems-engineering and verification evidence.','planned'),
  ('grad-aut640-thesis','aut-640','graduate',null,'Conduct and defend original automotive technology research using approved scholarly methods, transparent provenance, rigorous analysis, uncertainty treatment, and thesis-quality technical communication.','planned'),
  ('grad-aut650-capstone','aut-650','graduate',null,'Plan, develop, test, evaluate, and communicate an advanced automotive technology solution using systems reasoning, measurable requirements, validation evidence, and documented limitations.','planned'),
  ('grad-aut690-research-seminar','aut-690','graduate',null,'Critically evaluate and communicate current automotive research and emerging technology literature using transparent source provenance, methodological critique, uncertainty, and professional scholarly discussion.','planned')
